// https://risoume.github.io

let colors = ["#1A535C", "#4ECDC4", "#FFA96C", "#FF6B6B", "#FFE66D"]; //顏色調整

let n; //代表網格中每行和每列的弧線數量
let s;
let mult = 0.8;
let angles = new Array(4);

function setup() {
  createCanvas(600, 600); //設置畫布的大小為廣600像素，高600像素。
  rectMode(RADIUS);
  noStroke();
  noLoop();
  init();
}

function init() {
  n = int(random(5, 8)); //代表網格中有5行和8列的弧線數量
  s = width/(n+1);
}

function draw() {
  background("#fffbe6");
  for (i = 0; i < n; i++) {
    for (j = 0; j < n; j++) {
      arcs((i+1)*s, (j+1)*s, s*mult);
    }
  }
}

function arcs(x, y, size) {
  let x1 = int(random(-20, 20));
  let x2 = int(random(-20, 20));

  angles[0] = 45+x1;
  angles[1] = 45-x1;
  angles[2] = 45+x2;
  angles[3] = 45-x2;

  let lastAngle = 0;
  pushMatrix();
  translate(x, y);
  rotate(random(-PI, PI));
  let k = random(0.7, 1);
  for (i = 0; i < angles.length; i++) {
    fill(colors[int(random(colors.length))]);
    arc(0, 0, size*k, size*k, lastAngle, lastAngle+radians(angles[i]));
    lastAngle += radians(45 + angles[i]);
  }
  fill("#fffbe6");
  ellipse(0, 0, size/5, size/5);
  popMatrix();
}

function mouseReleased() {
  init();
  redraw();
}

